# url-suffix -> (name, cat, desc)
T = {
"petrifying-well-lymm/":("Petrifying Well, Lymm","spring","A lime-laden spring by Ridding's Brook near Lymm Dam that turned mosses and twigs to stone, recorded by the Victorian botanist Leo Grindon; exact spot now uncertain, location approximate."),
"billy-hobbys-well-chester/":("Billy Hobby's Well, Chester","well","Spring on the edge of Chester known from 18th-century field names; 'Hobby' may echo the hob, a goblin or demon name, hinting at old folklore attached to the water."),
"holy-well-alderley-edge/":("Holy Well, Alderley Edge","well","Spring beneath the Holy Well Rocks on Alderley Edge whose water was said in the 1840s to cure barrenness; a legend tells of a woman and cow buried by a falling boulder nearby."),
"st-ellens-well/":("St Ellen's Well, Harrisend Fell","well","Lonely moorland holy well 500 ft up on Harrisend Fell above Scorton, marked on the 1846 map; today just a spring among reeds with no surviving stonework."),
"holy-well-didsbury/":("Holy Well, Didsbury","well","Reputed ever-flowing spring near St James's old churchyard, once famed for health, magic and even prolonging life; believed lost to development."),
"robin-hoods-well-higham/":("Robin Hood's Well, Higham","well","Icy spring above the River Calder below Pendle Hall, once valued as a cure for certain ailments; current condition unknown."),
"holy-well-hollinshead/":("Holy Well, Hollinshead Hall","well","Elegant stone well house built over a spring beside the ruins of Hollinshead Hall near Tockholes, where water pours from a carved lion's head; pilgrims once came for its reputed cure for eye complaints. Reached by woodland paths."),
"fairy-well-preesall/":("Fairy Well, Preesall","well","Hilltop well at Preesall described in 1852 as all but deified; rags and clouts were tied to a nearby 'Beggar's Bush' with a prayer for healing."),
"bull-spring/":("Bull (Bel) Spring, Staining","spring","Spring issuing from a long stone mound at Hardhorn, linked by the Victorian cleric William Thornber to Hallowe'en bonfire cairns and seasonal rites; now largely forgotten."),
"fairy-well-staining/":("Fairy Well (Wrangdomwell), Staining","well","Cold spring between Hardhorn and Staining that local lore made a favourite haunt of kindly fairies, recorded by Rev. William Thornber in 1837."),
"minspit-well/":("Minspit Well, Preston","well","One of Preston's earliest wells, at the foot of the Church Street ridge and long a healing and water source; destroyed by later development."),
"calf-hey-well/":("Calf Hey Well, Briercliffe","well","Strong hillside spring rising into a square basin roofed with stone slabs; in medieval times its waters were believed to have special qualities."),
"walloper-well/":("Walloper Well, Newton-in-Bowland","well","Roadside spring in Bowland where generations of travellers, drovers and lead miners stopped to drink; still flowing."),
"dissenters-well/":("Dissenters' Well, Kelbrook","well","Moorland spring near Kelbrook where Quakers, Baptists and other Nonconformists met for outdoor worship in the 17th-18th centuries, away from parish churches."),
"peg-o-nells-well/":("Peg o' Nell's Well (St Margaret's Well)","well","Spring in the grounds of Waddow Hall by the Ribble, beside a headless statue probably of St Margaret; legend makes it the haunt of Peg o' Nell's spirit, whose statue was beheaded to lift her curse. Visible from the riverside footpath."),
"our-ladys-well-fernyhalgh/":("Our Lady's Well, Fernyhalgh","well","Marian well beside a shrine chapel at Fernyhalgh, said to have been revealed to a storm-saved merchant in the 15th century; still a Catholic pilgrimage site."),
"st-helens-well-sefton/":("St Helen's Well, Sefton","well","Once a pyramid-roofed well house noted for icy water good for rheumatism and sprains; now capped with an inscribed stone, though parishioners still visit on the saint's day."),
"shorey-well-burnley/":("Shorey Well, Burnley","well","Old Burnley well recorded by local antiquarian Clifford Byrne among the holy wells and healing springs of east Lancashire."),
"st-patricks-well-heysham/":("St Patrick's Well, Heysham","well","One of two old holy wells in Heysham village; its water has been diverted and an iron pump in a stone arch now marks the spot."),
"jinny-well-pendle/":("Jinny Well, Newchurch-in-Pendle","well","Spring trickling into a stone trough, haunted in folklore by Jinny's spirit, who wandered between the well and an old standing stone up the hill."),
"st-helens-well-colne/":("St Helen's Well, Colne","well","Holy well at Waterside on the south side of Colne, relocated in recent years by local researchers after its memory survived in the name of the former St Helen's Mill."),
"st-helens-well-whittle-le-woods/":("St Helen's Wells, Whittle-le-Woods","well","Celebrated well in a rugged part of Brindle parish where clear water bubbles through white sand; locals dropped crooked pins in for wishes, and its water was once carted round neighbouring villages for sale."),
"st-nicholas-well/":("St Nicholas' Well, Carlisle","well","Healing well near the medieval leper hospital of St Nicholas off Botchergate, prized for curing sores; people still filled 'shaking bottles' there in May in the 19th century. Destroyed by the railway."),
"st-cuthberts-well-carlisle/":("St Cuthbert's Well, Carlisle","well","Well in Carlisle's old market place linked to St Cuthbert's visit in 685 recorded by Bede; once sheltered by a pillared building called Carnaby's Folly, long since covered over."),
"st-helens-well-gosforth/":("St Helen's Well, Gosforth","well","Spring at Newton near Gosforth named in a charter of c.1220 as St Helen's Well at the corner of a garden; possibly surviving as a boggy spring above the farm."),
"holy-well-humphrey-head/":("Holy Well, Humphrey Head","spring","Medicinal spring below the limestone cliffs of Humphrey Head, near caves called the Fairy Church and Fairy Chapel; lead miners stayed for days drinking its strange-tasting water to purge poisons."),
"st-cuthberts-well/":("St Cuthbert's Well (Helly-well), Waverbridge","well","Once a copious spring of pure water where youths from surrounding villages held games on the second Sunday in May, with nothing stronger than the well water drunk; now only a trickle by a tree."),
"st-johns-well-dronfield/":("St John's Well, Dronfield","well","Spring-fed well by Dronfield church, recorded c.1710 as the source of water for baptising infants; survives with an old stone-lined shaft in the courtyard of a 16th-century forge."),
"nanny-well/":("Nanny's Well, Chapel-en-le-Frith","spring","Chalybeate spring, perhaps named for St Anne, where locals made 'Spanish water' with sugar or liquorice on Easter morning; now a disused iron pump, still dressed and blessed each July."),
"holy-well-kings-newton/":("Holy Well, King's Newton","well","Holy well recorded from 1366, given an arched stone well house by the royalist Hardinge family in 1662; the collapsed arch was later rebuilt by the community."),
"st-alkmunds-well-derby/":("St Alkmund's Well, Derby","well","Well of the Saxon saint Alkmund, recorded from 1190, with steps down to an oval basin in an 18th-century niche; a vicar was reputedly cured by its water and it has been dressed at times. Now railed off in a housing area."),
"hermits-well-dale-abbey/":("Hermit's Well, Dale Abbey","well","Ever-flowing well beside the rock-cut hermitage at Dale Abbey, which the founding hermit is said to have dug and blessed as holy and a cure for all ills."),
"silver-well/":("Silver Well, Ilkley Moor","well","Never-failing spring by Silver Well cottage on Ilkley Moor, thought by Victorian writers to have been a holy well, perhaps once given silver offerings; now covered by stone slabs but still running."),
"lady-well-ackworth/":("Lady Well, Ackworth","well","Ancient public well near Ladywell House in High Ackworth, probably dedicated to Our Lady; enclosed by the 1890s and now apparently lost, location approximate."),
"wishing-well/":("Wishing Well, Castley","well","Spring beneath Chapel Hill above the Wharfe, under a hawthorn, where village girls once made wishes; tradition placed a small chapel above it. Now just a boggy patch in the trees."),
"fairy-well-nostell/":("Fairy Well, Nostell","well","Well beside Fairy Wood near Nostell remembered in a local poem as a haunt of the little folk, who left when industry came; probable site only."),
"st-helens-well-barmby/":("St Helen's Well, Barmby-on-the-Marsh","well","Chalybeate well in St Helen's churchyard said to have medicinal powers; filled in during the 19th century and now remembered only in local memory."),
"st-peters-well-barmby/":("St Peter's Well, Barmby-on-the-Marsh","well","Sulphurous spring credited in 1831 with curing skin eruptions when applied externally; reportedly filled in during the 19th century and its exact position is now uncertain."),
"st-anns-well-welton/":("St Ann's Well, Welton","well","Holy well that once supplied Welton House, possibly the source of the village name; it survives under stone slabs in a copse north of St Anne's College."),
"fairy-well-liversedge/":("Fairy Well, Liversedge","well","Ruined little well house beneath a sycamore, marked on the 1854 map; its fairy folklore is forgotten and water now seeps into a small bog nearby."),
"old-wives-well/":("Old Wives' Well (Nattie Fontein), Stape","well","Spring bubbling into a small stone-lined chamber on the moors near Pickering, its lintel crudely carved 'Nattie Fontein'; the 'Old Wife' name may recall an ancient earth goddess."),
"holy-well-hudds/":("Holy Well, South Crosland","well","Spring emerging from a blasted rock face into a round trough beside an older square cistern, remembered locally as a wishing well; often choked with litter."),
"st-peters-well1/":("St Peter's Well, Leeds (North Hall)","well","Intensely cold spring near North Hall, long thought good for rheumatism and rickets and once served by a bathing house; covered over by 1846."),
"st-faiths-well-leven/":("St Faith's Well, Leven","well","Well by St Faith's Lane near the old churchyard, once the only drinking water for the Carrs; filled in c.1820 and its site re-found by a water diviner."),
"st-philips-well-keyingham/":("St Philip's Well, Keyingham","well","Wishing well tied to the local saint Philip Inglebred, with a stone dated 1667; country girls dropped pins or sixpences in for luck. Now filled in, leaving only boggy ground."),
"st-hildas-well-whitby/":("St Hilda's Well (Seynt-Hild-keld), Whitby","well","Spring near Grape Lane in Whitby recorded in 1396, later marked by the 'Virgin Pump' on Church Street; now destroyed, its site under a car park."),
"st-everildas-well/":("St Everilda's Well, Everingham","well","Well of the 7th-century local saint Everilda in the grounds of Everingham Priory, once open to villagers and praised for abundant excellent water; filled in before 1923."),
"low-well-bradford/":("Low Well, Bradford","well","Seemingly ordinary public well that local lore made Bradford's most supernatural water, haunted by ghosts and black dogs and used for scrying the future at 6 am."),
"holy-well-baildon/":("Halliwell (Holy Well), Baildon","well","Forgotten holy well below Halliway Banks Wood, recorded as Haliwell Bank in 1490 and reached by its own dedicated footpath on the 1852 map."),
"cloven-hoof-well/":("Cloven Hoof Well, Shipley Glen","well","Free-flowing, drinkable spring in mossy Shipley Glen, mapped in 1852 as Raygate Well; a hoof-print mark on the rock below gives it its devilish name."),
"st-peters-well-leeds/":("St Peter's Well, Leeds (St Peter's Square)","well","Intensely cold sulphurous spring at the foot of High Street, used for cold bathing against rheumatism and rickets according to Ralph Thoresby in 1715; long built over."),
"tun-well-eccleshill/":("Tun Well, Eccleshill","well","Deep village well recorded from 1618 under a large slab on Tunwell Lane, a drought-time supply; folklore placed a phantom black dog and a white lady on the lane."),
"brandy-well-carlton/":("Brandy Well, Carlton Bank","well","Roadside spring halfway up Carlton Bank whose peat-filtered water was said to have wonderful curative powers, with wishes made while drinking likely to come true; location approximate."),
"mannerly-well-gomersal/":("Mannerly (Manor Lea) Well, Gomersal","well","One of Gomersal's main wells, where boys filled bottles with liquorice and treacle on Palm Sunday to make sweet 'Spanish water' and swap tastes."),
"lady-well-leeds/":("Lady Well, Leeds","well","Copious spring of soft water by Lady Lane near Quarry Hill, close to the medieval Chantry of Our Lady; now lost beneath city buildings."),
"st-francis-well-conisborough/":("St Francis' Well, Conisbrough","well","Town well near the castle under a small steep-roofed conduit house; legend says a local holy man struck the spring from the ground during a drought in 1320-21. Now dry."),
"st-peters-well-york-minster/":("St Peter's Well, York Minster","well","Ancient spring in the crypt of York Minster, traditionally where King Edwin was baptised at Easter 627, prompting the first wooden church on the site; no longer open to visitors."),
"spink-well/":("Spink Well, Bradford","well","Spring below which Spinkwell House offered health-giving cold baths from 1788; gravestones of 1645 plague victims were built into its well house. Now neglected and muddy."),
"lady-well-hartshead/":("Lady Well, Hartshead","well","Clear spring flowing into a stone trough beneath an old hawthorn on Lady Well Lane leading to St Peter's Church; local tradition links it to baptisms by St Paulinus and to Robin Hood."),
"birley-spa-birley-sheffield/":("Birley Spa, Sheffield","spring","Spring developed as a cold bath in the early 1700s and rebuilt as a seven-bath spa by Earl Manvers in 1843; the restored bath house opens to the public on volunteer open days."),
"crutch-well/":("Crutch Well, Baildon","spring","Clear medicinal spring mapped in 1851, said never to run dry; it flows beneath the Cricketer's Arms opposite, keeping the cellar cool, with a cup-marked stone just above."),
"st-helens-well-eshton/":("St Helen's Well, Eshton","well","One of the most copious springs in England, boiling up into a circular pool by the road near Eshton Hall, recorded with a chapel in 1429; offerings are still tied to nearby shrubs. A listed monument."),
"horncliffe-well/":("Horncliffe Well, Hawksworth Moor","well","Renowned moorland well recorded in 1273 at the meeting point of three townships, famed for never running dry even in 1976; sadly its flow has since failed."),
"new-edge-chalybeate/":("New Edge Chalybeate, Colden","spring","Iron-rich spring trickling from an old stone trough beside New Edge above Colden, staining everything rust-red; such waters were valued for the blood and fatigue."),
"st-georges-well-harrogate/":("St George's Well, Harrogate","spring","Walled chalybeate spring off Parliament Street rediscovered c.1792, locally valued as an eye-wash for sore eyes before becoming one of Harrogate's spa wells; now lost."),
"holy-well-sennon/":("St Sennen's Well, Sennen Cove","well","Holy well 'of some repute' by the old Chapel Idne at Sennen Cove, whose water features in the Arthurian legend of the battle of Vellan-druchar; now lost, probably one of two mapped springs."),
"holy-well-lawhitton/":("Holy Well, Lawhitton (Barton Farm)","well","Holy well in a valley north of St Michael's church, recorded in 1914 and visited in 1980; by 1998 only a natural basin by a small bridge remained."),
"st-georges-well-taunton/":("St George's Well (Fons George), Wilton","well","Noted spring south of St George's church in Wilton, Taunton, where the afflicted came for cures said to be marvellous; its site was already uncertain by 1873, location approximate."),
"st-chads-well/":("St Chad's Well, Logierait","well","Renowned holy well behind Logierait church; tradition says its spirit was so offended when the saint's-day market on 22 August was stopped that the water vanished."),
"st-brides-well/":("St Bride's Well, Port-na-Craig, Pitlochry","well","Well by the medieval monks' ferry over the Tummel, dedicated to St Bride so travellers could seek her protection, usually by dropping in a brass pin or coin; lost about a century ago."),
"st-ninians-well-blairgowrie/":("St Ninian's Well, Blairgowrie","well","Well in Blairgowrie's Wellmeadow where tradition says St Ninian camped, drank and baptised converts; later covered over and piped into the town drains."),
"whooping-cough-well/":("Whooping Cough Well (Sput na Fruith-chasd), Strathtay","well","Spring spouting from a high rock by the Tullypowrie Burn, resorted to for curing whooping cough and counted among the three most important wells of the Tay valley; now overgrown."),
"kinkhoast-well/":("Kinkhoast Well, Comrie","well","Whooping-cough healing well in the hills above Comrie, recently revived and signposted by locals; its little pool is full of smooth white quartz pebbles left as offerings."),
"lady-well-ardgay/":("Lady's Well, Kincardine (Ardgay)","well","Spring of excellent water at the foot of the 'Bank of the Gate' below the old Clan Ross castle site; the Ordnance Survey found it under the sea at high tide."),
"holy-well-glen-prosen/":("Holy Well, Glen Prosen","well","Clear iron-bearing spring in remote Glen Prosen, reached by a straight stone-lined path from a ruined 17th-century chapel; a scatter of quartz stones may once have ringed it. Still drinkable."),
"58909/":("Tobar Ruadh (Red Well), Heaste, Skye","spring","Roadside chalybeate well between Broadford and Heaste where travellers drank from a pewter mug; fishermen took its water to pregnant women in Elgol. Recently cleared, with a tin mug left at the roadside."),
"st-marys-well-inchberry/":("St Mary's Well, Inchberry","well","Holy well and pool beside the Spey behind the Duff family mausoleum; pilgrims came on the first Sunday in May, leaving a stone offering, and its water was said to cure whooping cough, eye and joint troubles."),
"holy-well-farr/":("Holy Well by Loch ma Naire, Strathnaver","well","Lost holy well near Loch ma Naire, where crowds came twice yearly before sunrise to bathe, walk round the loch, drink from the well and throw in coins for cures; location approximate."),
"st-helens-well-maybole/":("St Helen's Well, Maybole","well","Well on the old road to Ayr, famous in the 17th century for curing 'unthriving children', with crowds gathering especially at May Day; covered over in the 1950s."),
"sulphur-well/":("Sulphur Well, Earlston","spring","One of Earlston's old 'verter' (virtue) wells, a sulphurous moorland spring whose 'gunpowder'-tasting water a local farmer credited with curing a serious internal complaint; lost in the 1800s, location approximate."),
"st-patricks-well-kilpatrick/":("St Patrick's Well, Old Kilpatrick","well","Well beside the church in the village that tradition claims as St Patrick's birthplace, used for baptisms and by villagers for centuries until closed in the 1890s; a later fountain nearby carried the name."),
"holywell-tuxford/":("Holy Well, Tuxford","well","Cold spring by Holywell Farm reputed to cure scurvy and other skin diseases and to help rheumatism, used for water until the 1920s; now a boggy patch."),
"druids-well/":("Druid's Well, Sutton Park","well","Spring beyond Bracebridge Pool in Sutton Park, once under a well house and much frequented in the 19th century; probably originally dedicated to St Mary. Now a stone-lined hole."),
"st-johns-well-berkhampstead/":("St John's Well, Berkhamsted","well","Holy well, first linked to St James's chapel, where pagan-style rites drew a reprimand from Bishop Hugh of Lincoln in the 12th century; later a pilgrimage site whose water served a leper hospital."),
"stcuthbertswell/":("St Cuthbert's Well, Bonnington (Leith)","spring","Chalybeate well by the Water of Leith, given a well house c.1818 where visitors paid a penny a drink; analysed as rich in iron salts, but destroyed in the 19th century."),
"st-stephens-well/":("St Stephen's Well, Banbury","spring","Slow chalybeate spring on the west side of Banbury, still often visited in 1841 and leaving a red deposit in its stone channel; built over later in the century."),
"holy-well-shoreditch/":("Holy Well, Shoreditch","well","The 'Haliwelle' recorded c.1100 that named Holywell Lane and the medieval priory, once sweet and frequented by scholars on summer evenings but spoiled by 1603; long destroyed."),
"st-johns-well-winkburn/":("St John's Well, Winkburn","well","Holy well near Holywell Farm, probably linked to the Knights Hospitallers who held Winkburn manor; its water was said to be good for sore eyes. Now an overgrown muddy patch."),
"brides-well-ballintemple/":("Bride's Well, Ballintemple","well","Well beside a stream just north-west of an old church site in Co. Wicklow, probably dedicated to St Brigid; still visible in 1927 but now in woodland and condition unknown."),
"st-patricks-well2/":("St Patrick's (Chapel) Well, Struthill","well","Spring beside the overgrown ruins of a chapel by the Machany Water, so venerated that the Presbytery ordered the chapel demolished c.1650 to suppress the 'superstitions' practised there; now a boggy seep."),
"st-serfs-well-crieff/":("St Serf's Well, Ochtertyre","well","Plentiful spring of St Serf, patron of Monzievaird, where on Lammas Day people drank and left white stones, spoons or rags; now drowned beneath the waters of the loch at Ochtertyre."),
"mineral-well-glen-lyon/":("Mineral Wishing Well, Glen Lyon","spring","Gushing roadside mineral spring in Glen Lyon with a stone shelf for offerings, usually small pebbles, which were said to be replaced as fast as roadmen cleared them; offerings were still remembered in recent times."),
"lady-well-tibbermore/":("Lady Well, Tibbermore","well","Holy well of St Mary that gave Tibbermore ('great well') its name, near a church once held by the Bishops of Dunkeld; its site in a roadside paddock now shows no trace."),
"chapel-well-bankfoot/":("Chapel Well, Berryhill (Bankfoot)","well","Holy well by a lost chapel and burial ground on the banks of the Ordie, where locals drank on the first Sunday of May until the 19th century; destroyed c.1850, site now in forestry."),
"st-patricks-well-dunruchan/":("St Patrick's Well, Dunruchan","well","Boggy remnant of a holy well beside the lost chapel site just east of the Dunruchan standing stones; one of two St Patrick's wells in Muthill parish."),
"beltane-well-kenmore/":("Holy Well of Inchadney (Beltane Well), Kenmore","well","Quartz-edged well near a vanished church of the 'Holy Women', visited by crowds on Beltane morning until the mid-19th century; cleaning in 1914 turned up coins, buttons and a cross-marked stone."),
"trinity-well/":("Trinity Well, Trinity Gask","well","Spring south of the manse famed in pre-Reformation times for miraculous cures and protection against plague and witchcraft; still flowing from a wooded bank in 2014."),
"st-mungos-well/":("St Mungo's Well, Gleneagles","well","Strong cold spring gathering into a clear pool amid gorse in the Ochil foothills, mapped in 1860; no recorded traditions survive."),
"st-davids-well/":("St David's (St Cuthbert's) Well, Weem","well","Trickle collecting in a small stone pool beneath the crags of Weem Wood, once called St Cuthbert's Bath; later named for Sir David Menzies, who restored it and lived as a hermit in the nearby cave. Plaque and modern cross mark it."),
"st-marys-well/":("St Mary's Well, Callander","well","Quartz-lined holy well by the river at Callander, mapped in 1862 though overlooked by Scottish holy well surveys; still holding fresh water."),
"maidens-well/":("Maiden's Well, Glendevon","well","Fine stone-bordered spring below fairy-haunted Maiden Castle, said never to fail; legend says a princess imprisoned in Castle Campbell was allowed out to drink here."),
"st-fillans-well/":("St Fillan's Well, Dundurn (Comrie)","well","Healing spring said to have moved from the top of Dundurn hill to its foot in disgust; in 1791 seventy invalids came on 1 May and 1 August, walking sunwise three times, bathing, casting white stones on the saint's cairn and leaving rags. Especially sought by the childless."),
"st-bennets-well/":("St Bennet's Well, Cromarty","well","Clootie well near the high-water mark below the ruined St Bennet's Chapel, where the sick drank and hung rags as offerings; in the 1930s wishers still left a scrap of clothing on the branches."),
"isle-maree/":("Holy Well of Isle Maree, Loch Maree","well","Well of St Maelrubha on a sacred island in Loch Maree, famed for curing insanity; beside it stood a wishing tree so studded with hammered-in coins that it died. Reached only by boat."),
"st-francis-well-dundee/":("St Francis' Well, Dundee","well","Cold spring on the sunny slopes of the Greyfriars' meadows north of the Howff, dedicated by the friars and reckoned the favourite of Dundee's holy wells; repaired after the Reformation but long since lost."),
"lady-well-dundee/":("Lady Well, Dundee","well","Bright spring flowing from under the Chapelshade braes near the old Chapel of Our Lady, recorded in 1409 and later feeding the town's water supply; now drained beneath the Ladywell roundabout."),
"st-marys-well-lethnot/":("St Mary's Well, Lethnot","well","Natural spring at the foot of a bank near Lethnot church, where silver coins left as votive offerings were found in the 19th century; the parish name may come from a word for a sacred place."),
"st-aidans-well/":("St Aidan's (St Iten's) Well, Menmuir","well","Well by Menmuir church named for St Aidan of Lindisfarne, believed to cure asthma and skin diseases; drained in the 19th century, though water still issues from a roadside spout."),
"holy-well-balmossie-den/":("Holy Well, Balmossie Den","well","Old wishing or holy well of Monifieth on the north side of the A92 at Balmossie Bridge, marked by a stone set up by Thomas Erskine in 1847 on the supposed medieval site, inscribed 'Whosoever drinketh of this water shall thirst again'."),
"lady-well-airth/":("Lady Well, Airth","well","Holy well below Airth Castle whose visitors were hauled before the kirk session in 1657 for leaving money, walking in silence and keeping the water from touching the ground; now destroyed."),
"st-ninians-well-stirling/":("St Ninian's Well, Stirling","well","Ancient well in an old stone well house that gave its name to the St Ninians district of Stirling, beside a demolished chapel recorded from 1242."),
"st-mahas-well/":("St Maha's Well, Balmaha","well","Healing spring high on the boggy moors above Balmaha, overlooking the islands of Loch Lomond; the village name is thought to come from the same saint."),
"our-ladys-well-stirling/":("Our Lady's Well, Stirling","well","Holy well at the northern foot of Gowan Hill below Stirling Castle, drawn by J.S. Fleming in 1898; built over and destroyed in the 20th century."),
"airthrey-mineral-wells/":("Airthrey Mineral Wells, Bridge of Allan","spring","Cold mineral springs below the Ochils, noted by Defoe as useful against skin complaints, whose fame turned Bridge of Allan into a Victorian spa town; the old well house survives as a ruin."),
"fairy-well-logie/":("Holy (Fairy) Well, Logie","well","'Very fine well' at the foot of Dumyat rising from over sixty springs through sand, described in 1792 as much resorted to by Catholics; still runs clear."),
"chapel-well-cambusbarron/":("Chapel Well (Christ's Well), Cambusbarron","well","Called the most famous of Stirling's holy wells, a village water supply and ritual site whose customs drew repeated church complaints; now marked only by a notice board."),
"christs-well-blair-drummond/":("Christ's Well, Blair Drummond","well","Well where local people practised healing rites condemned in old church records, probably the 'Christ's Well' of Menteith described in 1618 as hung all about with rags; exact location disputed."),
"st-corbets-well/":("St Corbet's Well, Touch Glen","well","Lonely spring in Touch Glen near Gilmour's Linn whose virtue lasted one hour a year: drinking at sunrise on the first Sunday of May was believed to preserve your life for twelve months. Long reduced to a boggy spring, location approximate."),
"st-finglassins-well/":("St Finglassin's Well, Kinglassie","well","Holy well of the saint who gave Kinglassie its name, sheltered by hawthorn and elder; the spring has been piped and bricked for water supply."),
"st-andrews-well-may/":("St Andrew's Well, Isle of May","well","Walled spring beside the Altar Stones on the Isle of May, the island's best water and its main domestic supply, though prone to drying in summer."),
"our-ladys-well-gateside/":("Our Lady's Well, Gateside","well","Small spring by the mill dam at Gateside beside the supposed site of St Mary's Chapel, remembered as a source of holy water before the Reformation."),
"tobar-mor-gigha/":("Tobar Mor (Well of the Winds), Gigha","well","Magical well on Cnoc Largie kept by an old woman guardian who, for silver, would clean it with a white clamshell, stir it sunwise and fling water toward the wind wanted by sailors; left uncovered it was said it could flood the island."),
"tobar-na-h-aoise-iona/":("Tobar na h-Aoise (Well of Age), Iona","well","Natural pool near the summit of Dun I on Iona, the 'well of eternal youth', where pilgrims came at dawn to touch the water as the first sunbeam struck it to renew their youth."),
"tobar-na-gaoithe-tuath-iona/":("Tobar na Gaoithe Tuath (North Wind Well), Iona","well","Lost magic well north of Cnoc nam Bradhan near the Hermit's Cell, where sailors left offerings to summon a north wind; location approximate."),
"tobar-nam-buadh-st-kilda/":("Tobar nam Buadh (Well of Virtues), St Kilda","well","Exceedingly cold spring near the Amazon's House on Hirta, described by Martin Martin in 1703 as a cure for colic, gravel and headaches; votaries once left humble offerings on a stone altar beside it."),
"lighthouse-well/":("Lighthouse Well, Dunnet Head","well","The most northerly healing well on mainland Britain, a stone-surrounded spring with two troughs that also served the keepers of Dunnet Head lighthouse, who carried its water half a mile uphill."),
"trows-well/":("Trows Well, Birsay","well","Spring by the Loch of Boardhouse in Orkney once believed to be the home of a trow, the island troll; its folklore is now forgotten but the spring still flows."),
"tobar-na-cailleach-banffshire/":("Tobar na Cailleach, Keith","well","Woodland 'well of the old woman' on Cairds Hill, once known for curing ailments and linked to a tale of the Cailleach bathing here and emerging young; still running as a dammed pool."),
"white-wells-ilkley/":("White Wells, Ilkley Moor","spring","Celebrated healing spring on Ilkley Moor, enclosed c.1760 by Squire Middleton in a white bath house with plunge baths for the 'cold water cure'; the building is open and water still runs into a plunge pool."),
"holy-well-hildenley/":("Holy Well, Hildenley","well","Copious pure spring at the edge of Hildenley Wood near Malton running into a small well house and pool, said to have been much used by the monks of Kirkham Abbey and still credited with healing virtues in 1859."),
"st-helens-well-thorp-arch/":("St Helen's Well, Thorp Arch","well","Ancient healing spring by St Helen's Beck in Chapel Wood near the Wharfe, close to a lost chapel and cross at St Helen's Ford; reputedly haunted and venerated since pre-Roman times."),
"st-helens-well-holbeck/":("St Helen's Well, Holbeck","spring","Medicinal holy well by St Helen's Bridge in Holbeck, once beside a chapel, later known as the Holbeck Spa Well; lost to industrial Leeds."),
"st-lamberts-well-burneston/":("St Lambert's Well, Burneston","well","St Lambert's 'fountain', recorded in the 12th century and probably in the present churchyard; it is thought to have given its name to the Halikeld ('holy spring') wapentake."),
"st-michaels-well/":("St Michael's Well, Well","well","One of the springs that named the village of Well, where an iron cup once hung for travellers; a Roman bath house stood nearby."),
"holy-well-todmorden/":("Holy Well, Todmorden","well","Spring of excellent water on the former Holy Well Lane, where local people once left 'memaws' — rags, coins and flowers — as offerings to the water."),
"sore-eye-well/":("Sore Eye Well, Eldwick","well","Moorland well where people bathed their faces to cure poor sight and eye complaints, hanging rags on an old rowan tree as offerings; now under a water-authority cover."),
"eyebright-well-leeds/":("Eyebright Well, Leeds","well","Well near the Monk Pits recorded by Ralph Thoresby in 1715 as long esteemed a sovereign remedy for sore eyes; lost to the growth of Leeds in the 19th century."),
"blind-well-sutton/":("Blind Well, Sutton-in-Holderness","well","Healing well in the East Field near Spring Cottage Farm where villagers bathed sore eyes; long lost, location approximate."),
"horley-green/":("Horley Green Spa, Halifax","spring","Chalybeate spring with May Day traditions, enclosed in a spa house and prominent in Calderdale's history from the late 18th to late 19th century."),
"wigglesworth-spa/":("Sulphur Well (Spa), Wigglesworth","spring","Sulphur spring under a small well house dated 1666, said in 1765 to have been used 'time out of mind' for healing."),
"hawklemass-well-whittingham/":("Hawklemass Well, Whittingham","well","Well with a stone trough near Howbalk Lane end, haunted by the 'Hawklemass Ghost', which village youths dreaded passing after dark."),
"lee-hall-well-bellingham/":("Lee Hall Well, Bellingham","well","'Excellent spring' at Lee Hall where the lady of the hall dipped children with rickets on Whitsun, Midsummer and St Peter's Eves, said to bring either a speedy cure or death; exact spot lost, location approximate."),
"st-helens-well-hartlepool/":("St Helen's (Freemen's) Well, Hartlepool","well","Well in the Far-well Field beside the site of St Helen's Chapel, recorded c.1200; still visible in 1823 but now gone."),
"bedes-well-hebburn/":("Bede's Well, Hebburn","well","Well in a small railed amphitheatre, enclosed in 1932, which legend says Bede's monks visited from Jarrow for water; now dry after its spring was diverted by shipyard slag works."),
"worm-well-lambton-durham/":("Worm Well, Fatfield","well","Wishing well at the foot of Worm Hill tied to the Lambton Worm legend, where crooked pins were offered and Midsummer Eve festivities held; reportedly restored in 1974."),
"st-martins-well-looe/":("St Martin's Well, Looe","well","Spring flowing from a rock on the old parish boundary path above Looe, much used by villagers for its excellent water before being enclosed in a shed and piped to the town."),
"holy-well-gunwalloe/":("Holy Well, Gunwalloe","well","Rock basin just below the porch of St Winwaloe's church on the shore at Gunwalloe, filled with sand at every high tide; already ruined by 1875."),
"st-agnes-well-cothelstone/":("St Agnes' Well, Cothelstone","well","Scheduled well in a small well house, said to be a powerful wishing well for divining love, though some locals avoided it as a haunt of mischievous pixies."),
"fairy-well/":("Fairy Well, Barrow Gurney","well","Spring in a dip by the stream near Barrow Wood, long visited to bathe sore eyes; a dedicated cup was kept there for drinking."),
"columbas-well-derry/":("St Columb's Wells, Derry","well","Three sacred springs outside Derry's walls named in the annals for Adomnán, Martin and Columba; already declining by 1837, now gone."),
"st-patricks-well-donegal/":("St Patrick's Well, Grianan of Aileach","well","Well between the outer ramparts of the Grianan of Aileach where Patrick is said to have baptised Prince Eoghan; pilgrims once pushed pins into a tree beside it."),
"our-ladys-well1/":("Our Lady's Well, Liberton","well","Virgin Mary's well by the Braid Burn, praised in 1792 for its large flow and light, wholesome water; now lost."),
"wells-o-wearie/":("Wells o' Wearie, Duddingston","well","One of a ring of sacred and healing springs around Arthur's Seat, renowned for its water; disrupted when the railway cut into the hill, site approximate."),
"druids-well-bingley/":("Druid's Well, Bingley","spring","Sweet spring seeping from beneath a lichen-covered boulder below the Druid's Altar crag near Bingley, near the lost 'Altar Well'."),
"wallaces-well-dunfermline/":("Wallace's Well (Well of Spaw), Dunfermline","well","Overgrown stone ruin of a reputed spring beside the path through Pittencrieff Glen, dedicated to William Wallace; in 1773 the council fought to keep the townsfolk's right of access to the 'Well of Spaw'."),
"vicars-well-musselburgh/":("Vicar's Well, Musselburgh","well","Holy well by the Dam Brae, attached to the vicarage of St Michael's church and celebrated in 1857 for the excellence of its water."),
"twentypenny-well/":("Twentypenny Well, Duddingston","well","Little-known healing well on the slopes of Arthur's Seat, still running clear into a stone trough by the path; its name may recall coin offerings."),
"st-michaels-well-edinburgh/":("St Michael's Well, Cowgate, Edinburgh","well","Holy well of the dragon-slaying archangel near the Cowgate and St Mary's Street, shown on a sketch of the city c.1540; possibly remembered in the later 'Silverwell Close'. Long gone."),
"old-wifes-spring-snaizholme/":("Old Wife's Spring, Snaizeholme","spring","Remote spring on a steep slope in Snaizeholme valley whose name may recall the Cailleach or old earth goddess; known only from place-name records."),
"dragons-well-wharncliffe/":("Dragon's Well, Wharncliffe","well","Well beneath Wharncliffe Crags where the legendary seven-headed Wharncliffe Dragon was said to drink, close to the Dragon's Den and the 'Old Wife's Cellar'."),
"holy-ash-well-bradford/":("Holy Ash Well (Hellywell), Bradford","well","Healing spring of wide renown off Manningham Lane, with a Wart or Pin Stone beside it; now under or beside Valley Parade football ground."),
"claymore-well-kettleness/":("Claymore Well, Kettleness","well","Well near Kettleness where fairies were said to wash their linen and beat it with bittle and pin, the noise carrying a mile on fairy washing nights."),
}
